import { afterEach, describe, expect, it, vi } from "vitest";
import {
  isFactorId,
  isTotpCode,
  needsStaffChallenge,
  safeTotpQr,
  staffDeadline,
  STAFF_REQUEST_DEADLINE_MS,
  STAFF_TOTP_QR_MAX_CHARACTERS,
} from "./staff-entry";

afterEach(() => vi.useRealTimers());
describe("staff entry input and bounded waits", () => {
  it("accepts the provider generator's XML declaration/comment prefix", () => {
    const raw =
      'data:image/svg+xml;utf-8,<?xml version="1.0"?>\n<!-- Generated by SVGo -->\n<svg xmlns="http://www.w3.org/2000/svg"></svg>\n';
    expect(safeTotpQr(raw)).toContain(
      "data:image/svg+xml;charset=utf-8,%3Csvg%20",
    );
    expect(safeTotpQr(raw)).not.toContain("xml%20version");
  });
  it.each([
    '<!DOCTYPE svg [<!ENTITY x SYSTEM "file:///private">]>',
    '<?xml-stylesheet href="https://attacker.test/style"?>',
    "<!-- unrecognized provider prefix -->",
  ])("rejects unsupported QR prologs %s", (prefix) => {
    expect(
      safeTotpQr(
        "data:image/svg+xml;utf-8," +
          prefix +
          '<svg xmlns="http://www.w3.org/2000/svg"></svg>',
      ),
    ).toBeNull();
  });
  it.each([
    "12345",
    "1234567",
    " 123456",
    "123456 ",
    "１２３４５６",
    "<svg>",
    "",
  ])("rejects a malformed code %s", (value) =>
    expect(isTotpCode(value)).toBe(false),
  );
  it("accepts the authenticator's exact six digits including leading zeroes", () =>
    expect(isTotpCode("012345")).toBe(true));
  it.each([
    ["aal1", "aal1"],
    ["aal1", "aal2"],
    ["aal2", "aal1"],
    [null, "aal2"],
    ["aal2", undefined],
  ])("requires a challenge for stale/unverified assurance %s %s", (a, b) =>
    expect(needsStaffChallenge(a, b)).toBe(true),
  );
  it("recognizes AAL2 without calling it recent-action proof", () =>
    expect(needsStaffChallenge("aal2", "aal2")).toBe(false));
  it.each([
    null,
    {},
    "not-a-factor",
    "https://attacker.test",
    "00000000-0000-0000-0000-000000000000",
  ])("rejects an invalid factor identifier %#", (value) =>
    expect(isFactorId(value)).toBe(false),
  );
  it("accepts an actual factor UUID", () =>
    expect(isFactorId("2d734acd-a974-45f1-aabc-bc9b0a37fb40")).toBe(true));
  it("encodes the installed provider's raw SVG data URI without an external image request", () =>
    expect(
      safeTotpQr(
        'data:image/svg+xml;utf-8,<svg xmlns="http://www.w3.org/2000/svg"></svg>',
      ),
    ).toBe(
      "data:image/svg+xml;charset=utf-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%3E%3C%2Fsvg%3E",
    ));
  it.each([
    "https://attacker.test/qr",
    "data:text/html,<svg></svg>",
    "javascript:alert(1)",
    "data:image/svg+xml;utf-8,<script></script>",
    "data:image/svg+xml;utf-8,<svg ",
  ])("refuses non-provider QR data %#", (value) =>
    expect(safeTotpQr(value)).toBeNull(),
  );
  it("accepts the observed provider SVG size without storing a real factor secret", () => {
    const prefix =
      'data:image/svg+xml;utf-8,<?xml version="1.0"?>\n<!-- Generated by SVGo -->\n<svg xmlns="http://www.w3.org/2000/svg"><!--';
    const suffix = "--></svg>";
    const raw =
      prefix + "x".repeat(362_656 - prefix.length - suffix.length) + suffix;
    expect(safeTotpQr(raw)).toContain(
      "data:image/svg+xml;charset=utf-8,%3Csvg%20",
    );
  });
  it("accepts the exact input ceiling and rejects one extra character", () => {
    const prefix =
      'data:image/svg+xml;utf-8,<svg xmlns="http://www.w3.org/2000/svg"><!--';
    const suffix = "--></svg>";
    const raw =
      prefix +
      "x".repeat(STAFF_TOTP_QR_MAX_CHARACTERS - prefix.length - suffix.length) +
      suffix;
    expect(raw).toHaveLength(STAFF_TOTP_QR_MAX_CHARACTERS);
    expect(safeTotpQr(raw)).not.toBeNull();
    expect(safeTotpQr(raw.replace("--></svg>", "x--></svg>"))).toBeNull();
  });
  it("releases a successful wait timer", async () => {
    vi.useFakeTimers();
    await expect(staffDeadline(Promise.resolve("ok"))).resolves.toBe("ok");
    expect(vi.getTimerCount()).toBe(0);
  });
  it("bounds a stalled request without claiming its side effect was cancelled", async () => {
    vi.useFakeTimers();
    const request = staffDeadline(new Promise(() => {}));
    const assertion = expect(request).rejects.toThrow("timed out");
    await vi.advanceTimersByTimeAsync(STAFF_REQUEST_DEADLINE_MS);
    await assertion;
    expect(vi.getTimerCount()).toBe(0);
  });
});
